/* StatSlam site — renders the published-video gallery from videos.json.
 *
 * videos.json is regenerated by the publishing pipeline
 * (~/.openclaw/scripts/sports/sync_statslam_site.py), so every automated post
 * shows up here without touching the HTML. TikTok posts get added to the same
 * records once the Content Posting API is approved.
 */
(function () {
  "use strict";

  var DATA_URL = "videos.json";

  function fmtDate(iso) {
    if (!iso) return "";
    var d = new Date(iso);
    if (isNaN(d)) return "";
    return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
  }

  function fmtNum(n) {
    return typeof n === "number" ? n.toLocaleString("en-US") : n;
  }

  /* Published titles carry decorative emoji for the platform feeds.
     They add nothing here, so strip them for on-site display only —
     videos.json keeps the exact published title. */
  function cleanTitle(t) {
    return (t || "")
      .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu, "")
      .replace(/\s{2,}/g, " ")
      .trim();
  }

  function videoCard(v) {
    var el = document.createElement("article");
    el.className = "video";

    var link = document.createElement("a");
    link.href = v.url || ("https://www.youtube.com/watch?v=" + v.youtube_id);
    link.target = "_blank";
    link.rel = "noopener";

    var img = document.createElement("img");
    img.className = "thumb";
    img.loading = "lazy";
    img.alt = cleanTitle(v.title) || "StatSlam video";
    img.src = v.thumbnail || ("https://i.ytimg.com/vi/" + v.youtube_id + "/mqdefault.jpg");

    var meta = document.createElement("div");
    meta.className = "meta";

    var t = document.createElement("p");
    t.className = "title";
    t.textContent = cleanTitle(v.title);

    var d = document.createElement("p");
    d.className = "date";
    d.textContent = fmtDate(v.published_at);

    meta.appendChild(t);
    meta.appendChild(d);
    link.appendChild(img);
    link.appendChild(meta);
    el.appendChild(link);
    return el;
  }

  function renderStats(node, data) {
    var s = data.channel || {};
    var pairs = [
      [fmtNum(s.video_count), "videos published"],
      [fmtNum(s.view_count), "total views"],
      [fmtDate(data.generated_at), "data last synced"]
    ];
    node.innerHTML = "";
    pairs.forEach(function (p) {
      if (p[0] === undefined || p[0] === null || p[0] === "") return;
      var box = document.createElement("div");
      var num = document.createElement("div");
      num.className = "num";
      num.textContent = p[0];
      var lbl = document.createElement("div");
      lbl.className = "lbl";
      lbl.textContent = p[1];
      box.appendChild(num);
      box.appendChild(lbl);
      node.appendChild(box);
    });
  }

  function render(data) {
    var statsNode = document.querySelector("[data-statslam-stats]");
    if (statsNode) renderStats(statsNode, data);

    var grid = document.querySelector("[data-statslam-videos]");
    if (!grid) return;

    var limit = parseInt(grid.getAttribute("data-limit") || "0", 10);
    var list = (data.videos || []).slice();
    if (limit > 0) list = list.slice(0, limit);

    grid.innerHTML = "";
    if (!list.length) {
      grid.innerHTML = '<p class="loading">No videos to show yet.</p>';
      return;
    }
    list.forEach(function (v) {
      grid.appendChild(videoCard(v));
    });
  }

  function fail() {
    var grid = document.querySelector("[data-statslam-videos]");
    if (grid) {
      grid.innerHTML =
        '<p class="loading">Could not load the video list right now. ' +
        'You can browse every episode on ' +
        '<a href="https://www.youtube.com/channel/UCykGZb7YAiOY0vbCv45OD5A" target="_blank" rel="noopener">' +
        'the StatSlam channel</a>.</p>';
    }
  }

  fetch(DATA_URL, { cache: "no-cache" })
    .then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    })
    .then(render)
    .catch(fail);
})();
